<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { IconImage, IconInfoCircle, IconArrowRight, IconBarChart, IconApps } from '@arco-design/web-vue/es/icon'
import type { AnalysisCase, RecordValue } from '@/api/workbench'
import { apiUrl } from '@/api/workbench'
import { workspace } from '@/services/workspace'
import { record, rows, text, number, friendly, formatValue, mediaOptions as buildMediaOptions, channelCode, channelLabel } from '@/services/presentation'
import { waferDisplayExtent, waferRegionContains } from '@/services/wafer-regions'
import { legacyMeasurements, observationTitle, scopeLabel, windowSamplingSeconds } from '@/services/analysis'
const props = defineProps<{ caseItem: AnalysisCase; frame: RecordValue; focusObsId: string; supportObsIds: string[]; counterObsIds: string[]; usedObsIds: string[] }>()
const emit = defineEmits<{ focus: [id: string] }>()
const mediaKind = ref('image'), mediaError = ref(false), observationSearch = ref('')
const observations = computed(() => rows(props.frame.observations))
const focus = computed(() => observations.value.find((o) => o.obs_id === props.focusObsId) ?? null)
const dataset = computed(() => text(props.frame.source_dataset))
const imageScope = computed(() => rows(props.frame.scopes).find((s) => s.kind === 'image_region'))
const mediaOptions = computed(() => buildMediaOptions(props.caseItem.visual_evidence))
const activeMedia = computed(() => mediaOptions.value.find((v) => v.mediaKey === mediaKind.value) ?? mediaOptions.value[0])
const imageUrl = computed(() => text(activeMedia.value?.url ?? activeMedia.value?.preview_path))
const imageShape = computed(() => {
  const shape = Array.isArray(imageScope.value?.image_shape_hw) ? imageScope.value.image_shape_hw as number[] : [900, 900]
  return { height: shape[0] ?? 900, width: shape[1] ?? 900 }
})
const bbox = computed(() => Array.isArray(imageScope.value?.bbox_xyxy) ? imageScope.value!.bbox_xyxy as number[] : [])
const process = computed(() => legacyMeasurements(props.caseItem, 'process-measurements.v1'))
const processChannels = computed(() => {
  const stats = rows(process.value.channels), trends = rows(props.caseItem.process_trends)
  const merged = new Map<string, RecordValue>()
  stats.forEach((channel) => merged.set(channelCode(channel.channel), channel))
  trends.forEach((trend) => { const id = channelCode(trend.channel); merged.set(id, { ...merged.get(id), ...trend }) })
  const fields: Record<string, string> = { 'statistics.mean_z': 'mean_z', 'statistics.std_z': 'std_z', 'statistics.slope_z': 'slope_z', 'residual.contribution': 'contribution' }
  observations.value.forEach((observation) => {
    const code = channelCode(observation.subject_id), field = fields[text(observation.feature_id)]
    if (!code || !field || observation.status !== 'observed') return
    const channel = merged.get(code) ?? { channel: code }
    channel[field] = record(observation.value).number
    merged.set(code, channel)
  })
  return [...merged.values()].sort((a, b) => Number(b.contribution ?? 0) - Number(a.contribution ?? 0))
})
const semanticAppearance = computed(() => observations.value.find((o) => o.feature_id === 'appearance.semantic_candidates'))
const residualEnergy = computed(() => observations.value.find((o) => o.feature_id === 'residual.energy'))
const residualLimit = computed(() => observations.value.find((o) => o.feature_id === 'residual.normal_limit'))
const selectedChannel = computed(() => {
  const code = channelCode(focus.value?.subject_id)
  return processChannels.value.find((c) => channelCode(c.channel) === code) ?? processChannels.value[0]
})
const samples = computed(() => Array.isArray(selectedChannel.value?.samples) ? (selectedChannel.value!.samples as unknown[]).map(Number) : [])
const plot = computed(() => {
  const values = samples.value.filter(Number.isFinite)
  const min = Math.min(...values), max = Math.max(...values), spread = max - min || 1
  return { points: values.map((v, i) => `${35 + i / Math.max(values.length - 1, 1) * 445},${155 - (v - min) / spread * 120}`).join(' '), min, max, mid: min + (max - min) / 2 }
})
const windowScope = computed(() => rows(props.frame.scopes).find((s) => s.kind === 'time_window'))
const samplingSeconds = computed(() => windowSamplingSeconds(props.frame, process.value))
const waferMeasurement = computed(() => legacyMeasurements(props.caseItem, 'wafer-measurements.v1'))
const waferMap = computed<number[][]>(() => {
  const direct = props.caseItem.wafer_map
  const nested = record(record(props.caseItem.generated_evidence?.raw_evidence).extra)
  const value = direct ?? record(nested.wm811k).wafer_map ?? nested.wafer_map
  return Array.isArray(value) && Array.isArray(value[0]) ? value as number[][] : []
})
const zone = computed(() => {
  const scope = rows(props.frame.scopes).find((s) => s.scope_id === focus.value?.scope_id)
  return text(scope?.zone, 'all_valid')
})
const waferExtent = computed(() => waferDisplayExtent(waferMap.value))
function inZone(x: number, y: number) { return waferRegionContains(x, y, zone.value, waferExtent.value) }
const usedObservations = computed(() => observations.value.filter((o) => props.usedObsIds.includes(text(o.obs_id))))
const extraObservations = computed(() => observations.value.filter((o) => !props.usedObsIds.includes(text(o.obs_id)) && observationTitle(o, props.frame).toLowerCase().includes(observationSearch.value.toLowerCase())))
const spatialDensities = computed(() => observations.value.filter((o) => o.feature_id === 'spatial.failure_density'))
function selectChannel(channel: RecordValue) {
  const code = channelCode(channel.channel)
  const list = observations.value.filter((o) => channelCode(o.subject_id) === code)
  const selected = list.find((o) => props.supportObsIds.includes(text(o.obs_id))) ?? list.find((o) => o.feature_id === 'residual.contribution') ?? list[0]
  if (selected) emit('focus', text(selected.obs_id))
}
function observationClass(observation: RecordValue) {
  return { selected: props.focusObsId === observation.obs_id, supporting: props.supportObsIds.includes(text(observation.obs_id)), counter: props.counterObsIds.includes(text(observation.obs_id)) }
}
watch(() => props.caseItem.case_id, () => { mediaKind.value = 'image'; mediaError.value = false; observationSearch.value = '' })
watch(imageUrl, () => { mediaError.value = false })
</script>
<template>
  <section class="panel evidence-inspector"><header class="panel-header"><div><span class="eyebrow">OBSERVED</span><h2>样本与观测</h2></div><span class="tag">{{ observations.length }} 项实际观测</span></header>
    <div class="evidence-media"><div v-if="dataset === 'mvtec' && semanticAppearance" class="perception-summary"><span>观测到的异常现象</span><strong>{{ formatValue(semanticAppearance.value) }}</strong><small>ROI 外观模型输出 · 拍摄部位未确认</small></div>
      <template v-if="dataset === 'mvtec'"><div v-if="mediaOptions.length" class="media-tabs"><button v-for="(media, index) in mediaOptions" :key="text(media.artifact_id, String(index))" :class="{ active: activeMedia === media }" @click="mediaKind = media.mediaKey">{{ media.display }}</button></div><div v-if="imageUrl && !mediaError" class="image-stage"><svg v-if="activeMedia?.kind === 'image' && activeMedia?.source_key !== 'roi_path' && bbox.length === 4" :viewBox="`0 0 ${imageShape.width} ${imageShape.height}`" role="img" aria-label="原始图像与当前异常区域"><image :href="apiUrl(workspace.baseUrl, imageUrl)" :width="imageShape.width" :height="imageShape.height" @error="mediaError = true" /><rect :x="bbox[0]" :y="bbox[1]" :width="bbox[2]! - bbox[0]!" :height="bbox[3]! - bbox[1]!" fill="#3166df08" stroke="#6897ff" :stroke-width="Math.max(2, imageShape.width / 250)" stroke-dasharray="9 6" /><rect :x="bbox[0]" :y="bbox[1]! - 30" width="104" height="30" fill="#3166df" /><text :x="bbox[0]! + 10" :y="bbox[1]! - 10" fill="white" font-size="17">当前 ROI</text></svg><img v-else :src="apiUrl(workspace.baseUrl, imageUrl)" :alt="text(activeMedia?.display, '实际观测图像')" @error="mediaError = true" /></div><div v-else class="media-unavailable"><IconImage /><p>{{ mediaError ? '图像资产读取失败。观测与推理结果仍可检查。' : props.caseItem.media_note || '此 Evidence 没有附带可访问图像。可从原始图片重新运行并生成媒体。' }}</p></div><div v-if="bbox.length === 4" class="media-caption"><span class="roi-indicator" />当前异常区域 · 原图坐标 {{ bbox.map((v) => Math.round(v)).join(' / ') }}</div></template>
      <template v-else-if="dataset === 'tep'"><div class="window-context"><span class="tag tag--blue">完整窗口</span><strong>样本 {{ windowScope?.sample_start ?? process.sample_start }}–{{ windowScope?.sample_end ?? process.sample_end }}</strong><span>{{ samplingSeconds ? `每 ${samplingSeconds} 秒采样` : '按原始样本顺序' }}</span></div><div v-if="selectedChannel" class="process-plot"><div class="process-plot__heading"><strong>{{ channelLabel(selectedChannel.channel) }}</strong><span>原始窗口趋势</span></div><svg v-if="samples.length" viewBox="0 0 510 190" role="img" :aria-label="`${channelLabel(selectedChannel.channel)} 完整窗口趋势`"><line v-for="y in [35,95,155]" :key="y" x1="35" x2="480" :y1="y" :y2="y" stroke="#e8edf5" stroke-dasharray="3 4" /><text x="0" y="39">{{ number(plot.max,3) }}</text><text x="0" y="99">{{ number(plot.mid,3) }}</text><text x="0" y="159">{{ number(plot.min,3) }}</text><polyline :points="plot.points" fill="none" stroke="#5a82d7" stroke-width="1.8" /><text x="35" y="182">{{ windowScope?.sample_start ?? process.sample_start }}</text><text x="465" y="182">{{ windowScope?.sample_end ?? process.sample_end }}</text></svg><div v-else class="media-unavailable"><IconBarChart /><p>该 Evidence 保存统计观测，没有附带完整原始序列。</p></div></div><div v-if="processChannels.length" class="channel-table-scroll"><table class="channel-table"><thead><tr><th>变量 · {{ processChannels.length }} 通道</th><th>均值 z</th><th>残差贡献</th></tr></thead><tbody><tr v-for="channel in processChannels" :key="text(channel.channel)" :class="{ selected: channelCode(channel.channel) === channelCode(selectedChannel?.channel) }" tabindex="0" @click="selectChannel(channel)" @keydown.enter="selectChannel(channel)"><td>{{ channelLabel(channel.channel) }}</td><td>{{ number(channel.mean_z,3) }}</td><td><span class="contribution-value">{{ number(channel.contribution,3) }}</span><span class="contribution-track"><span :style="{ width: `${Math.min(100, Number(channel.contribution ?? 0) / Math.max(...processChannels.map((c) => Number(c.contribution ?? 0)), .00001) * 100)}%` }" /></span></td></tr></tbody></table></div><p v-if="residualEnergy || process.residual_energy !== undefined" class="media-caption">残差能量 {{ number(record(residualEnergy?.value).number ?? process.residual_energy) }} · 配套正常上限 {{ number(record(residualLimit?.value).number ?? process.normal_energy_limit) }}</p></template>
      <template v-else-if="dataset === 'wafer'"><div class="wafer-map-stage"><svg v-if="waferMap.length" :viewBox="`-1 -1 ${(waferMap[0]?.length ?? 1) + 2} ${waferMap.length + 2}`" role="img" :aria-label="`原始晶圆网格，突出${friendly(zone)}区域`"><template v-for="(row, y) in waferMap" :key="y"><rect v-for="(value, x) in row" :key="x" :x="x" :y="y" width=".84" height=".84" :fill="value === 0 ? '#f4f6fa' : value === 2 ? '#df9e63' : '#d2ddef'" :opacity="value === 0 || inZone(x,y) ? 1 : .22" rx=".12" /></template><ellipse v-if="waferExtent && ['center','middle'].includes(zone)" :cx="waferExtent.cx" :cy="waferExtent.cy" :rx="waferExtent.rx*.4" :ry="waferExtent.ry*.4" fill="none" stroke="#628ae0" stroke-width=".19" stroke-dasharray=".7 .5" /><ellipse v-if="waferExtent && ['middle','edge'].includes(zone)" :cx="waferExtent.cx" :cy="waferExtent.cy" :rx="waferExtent.rx*.8" :ry="waferExtent.ry*.8" fill="none" stroke="#628ae0" stroke-width=".19" stroke-dasharray=".7 .5" /></svg><img v-else-if="imageUrl" :src="apiUrl(workspace.baseUrl, imageUrl)" alt="实际晶圆网格" /><div v-else class="media-unavailable"><IconApps /><p>{{ caseItem.media_note || '此 Evidence 未附带原始网格。区域统计保留如下。' }}</p></div></div><div class="wafer-legend"><span><i class="die-good" />正常芯粒</span><span><i class="die-failed" />失效芯粒</span><span><i class="die-bg" />背景（不计分母）</span></div><div v-if="spatialDensities.length" class="zone-stats"><button v-for="density in spatialDensities" :key="text(density.obs_id)" :class="{ active: density.scope_id === focus?.scope_id }" @click="emit('focus', text(density.obs_id))"><span>{{ scopeLabel(frame,density.scope_id) }}</span><strong>{{ number(Number(record(density.value).number) * 100, 3) }}<small>%</small></strong><small>有效芯粒失效率</small></button></div><p v-if="waferMeasurement.valid_die_count" class="media-caption">有效 {{ waferMeasurement.valid_die_count }} / 失效 {{ waferMeasurement.failed_die_count }} 芯粒 · {{ friendly(waferMeasurement.classifier_pattern, '未提供分类') }}</p></template>
    </div>
    <div class="observations-block"><div class="section-heading"><div><h3>图谱实际检查的观测</h3><p>选择一项，联动区域、变量与右侧条件</p></div><span class="count-label">{{ usedObservations.length }}</span></div><div v-if="usedObservations.length" class="observation-list"><button v-for="observation in usedObservations" :key="text(observation.obs_id)" class="observation-row" :class="observationClass(observation)" @click="emit('focus', text(observation.obs_id))"><span class="observation-row__mark" /><span class="grow"><strong>{{ observationTitle(observation, frame) }}</strong><small>{{ scopeLabel(frame, observation.scope_id) }} · {{ observation.procedure_id === 'spatial-statistics' || observation.procedure_id === 'geometry' ? '测量值' : '模型 / 数值观测' }}</small></span><b>{{ observation.status === 'missing' ? '缺测' : formatValue(observation.value) }}</b><IconArrowRight /></button></div><div v-else class="muted">当前结果没有关联可执行观测条件。请检查右侧引擎依据与支持范围。</div><div v-if="focus" class="focused-observation"><IconInfoCircle /><span>{{ observationTitle(focus,frame) }}：<strong>{{ formatValue(focus.value) }}</strong><br /><small>范围：{{ scopeLabel(frame, focus.scope_id) }} · {{ props.supportObsIds.includes(text(focus.obs_id)) ? '参与当前候选的支持' : props.counterObsIds.includes(text(focus.obs_id)) ? '与当前候选冲突' : '不构成当前候选的完整支持' }}</small></span></div><details v-if="extraObservations.length || observationSearch" class="all-observations"><summary>其他保留的测量（{{ observations.length - usedObservations.length }}）</summary><input v-model="observationSearch" class="search-input" placeholder="按变量或特征查找" aria-label="搜索全部观测" /><div class="extra-observation-list"><button v-for="observation in extraObservations" :key="text(observation.obs_id)" :class="{ selected: observation.obs_id === focusObsId }" @click="emit('focus', text(observation.obs_id))"><span>{{ observationTitle(observation,frame) }}<small>{{ scopeLabel(frame,observation.scope_id) }}</small></span><strong>{{ formatValue(observation.value) }}</strong></button></div></details></div>
  </section>
</template>
<style scoped>
.evidence-inspector{overflow:hidden;}.perception-summary{padding:3px 0 19px;}.perception-summary>span{display:block;font-size:12px;color:#7f8ca1;margin-bottom:8px;}.perception-summary>strong{font-size:15px;line-height:1.7;color:#526e98;font-weight:550;display:block;}.perception-summary>small{display:block;font-size:11px;color:#8392a8;margin-top:6px;}.panel-header{padding:19px 21px;}.panel-header h2{font-size:16px;}.panel-header .eyebrow{font-size:11px;margin-bottom:5px;}.evidence-media{padding:16px 21px 0;}.media-tabs{display:flex;gap:15px;margin-bottom:14px;border-bottom:1px solid var(--border);overflow:auto;}.media-tabs button{border:0;border-bottom:2px solid transparent;background:none;padding:7px 0 9px;white-space:nowrap;font-size:13px;color:#8d99ad;}.media-tabs button.active{color:var(--blue);border-bottom-color:var(--blue);}.image-stage{background:#f5f7fb;border:1px solid #e9edf4;border-radius:7px;display:flex;align-items:center;justify-content:center;min-height:240px;overflow:hidden;}.image-stage>svg{max-height:370px;width:100%;}.image-stage>img{max-width:100%;max-height:370px;display:block;object-fit:contain;}.media-caption{font-size:12px;line-height:1.7;color:#7f8ca1;display:flex;align-items:center;gap:6px;margin:10px 0 15px;}.roi-indicator{width:7px;height:7px;border:1px solid var(--blue);display:inline-block;}.media-unavailable{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:38px 25px;background:#f6f8fc;border-radius:6px;color:#7f8ca1;text-align:center;min-height:190px;}.media-unavailable>svg{font-size:30px;margin-bottom:14px;}.media-unavailable p{font-size:13px;line-height:1.8;margin:0;max-width:320px;}.observations-block{padding:22px 21px;border-top:1px solid var(--border);}.observations-block h3{font-size:13px;margin:0;}.observations-block .section-heading p{font-size:12px;color:#7f8ca1;}.observation-list{border:1px solid var(--border);border-radius:6px;overflow:hidden;}.observation-row{display:flex;align-items:center;gap:9px;width:100%;padding:12px 11px;background:white;border:0;border-bottom:1px solid #edf0f5;text-align:left;}.observation-row:last-child{border-bottom:0;}.observation-row:hover{background:#fafbfe;}.observation-row.selected{background:#edf3ff;box-shadow:inset 2px 0 var(--blue);}.observation-row strong{display:block;color:#5c6d88;font-weight:500;font-size:13px;line-height:1.65;}.observation-row small{display:block;font-size:11px;color:#7f8ca1;margin-top:3px;}.observation-row b{max-width:40%;font-size:13px;font-weight:500;color:#4c658e;line-height:1.6;text-align:right;}.observation-row>svg{color:#7f8ca1;font-size:12px;}.observation-row__mark{width:5px;height:5px;border-radius:50%;background:#bec9da;flex-shrink:0;}.observation-row.supporting .observation-row__mark{background:#58a484;}.observation-row.counter .observation-row__mark{background:#cf7d7d;}.focused-observation{display:flex;gap:8px;margin-top:14px;font-size:13px;line-height:1.8;color:#6f85a7;background:#f5f8ff;padding:12px;border-radius:5px;}.focused-observation>svg{font-size:13px;flex-shrink:0;margin-top:3px;}.focused-observation strong{font-weight:500;color:#416ba8;}.focused-observation small{font-size:11px;color:#7f8ca1;}.all-observations{font-size:13px;color:#8390a6;margin-top:20px;}.all-observations>summary{cursor:pointer;}.all-observations>.search-input{margin-top:14px;min-height:32px;font-size:13px;padding-left:10px;}.extra-observation-list{max-height:350px;overflow:auto;margin-top:12px;}.extra-observation-list button{display:flex;gap:12px;justify-content:space-between;width:100%;background:none;border:0;border-bottom:1px solid var(--border);text-align:left;padding:10px 5px;font-size:12px;color:#7d8aa1;}.extra-observation-list button.selected{background:#edf3ff;}.extra-observation-list small{display:block;font-size:11px;color:#7f8ca1;margin-top:4px;}.extra-observation-list strong{font-weight:500;color:#5e7396;max-width:40%;text-align:right;}.window-context{display:flex;gap:9px;align-items:center;font-size:12px;color:#7f8ca1;margin:2px 0 18px;}.window-context strong{font-weight:500;color:#526a91;font-size:13px;}.window-context>span:last-child{margin-left:auto;font-size:11px;}.process-plot{background:#f7f9fd;border:1px solid #e5ebf5;border-radius:6px;padding:15px 14px 6px;}.process-plot__heading{display:flex;gap:10px;align-items:center;justify-content:space-between;margin-bottom:10px;}.process-plot__heading strong{font-size:13px;font-weight:500;color:#5d749b;}.process-plot__heading>span{font-size:11px;color:#7f8ca1;}.process-plot svg{width:100%;}.process-plot svg text{fill:#a2aec2;font-size:10px;}.channel-table-scroll{max-height:270px;overflow:auto;margin-top:15px;border:1px solid var(--border);border-radius:5px;}.channel-table{border-collapse:collapse;width:100%;font-size:12px;color:#8391a8;}.channel-table th{font-weight:400;text-align:left;background:#fafbfe;position:sticky;top:0;z-index:1;color:#7f8ca1;}.channel-table th,.channel-table td{padding:10px 11px;border-bottom:1px solid #edf0f5;}.channel-table tbody tr{cursor:pointer;}.channel-table tr.selected{background:#edf3ff;color:#5075b7;}.channel-table th:first-child{width:57%;}.channel-table th:nth-child(2){white-space:nowrap;}.contribution-value{font-size:11px;display:block;}.contribution-track{display:block;height:3px;width:60px;background:#e9eef7;margin-top:5px;border-radius:2px;}.contribution-track>span{display:block;height:100%;background:#a1b8e5;border-radius:2px;}.channel-table tr.selected .contribution-track>span{background:#5b82d3;}.wafer-map-stage{display:flex;align-items:center;justify-content:center;border:1px solid #e7ecf5;background:#f9fafc;border-radius:6px;padding:17px;}.wafer-map-stage>svg{max-width:340px;max-height:350px;width:100%;}.wafer-map-stage>img{max-width:100%;max-height:350px;}.wafer-legend{display:flex;gap:15px;justify-content:center;margin:13px 0 18px;font-size:11px;color:#7f8ca1;}.wafer-legend>span{display:flex;align-items:center;gap:4px;}.wafer-legend i{width:6px;height:6px;border-radius:1px;background:#d2ddef;}.wafer-legend .die-failed{background:#df9e63;}.wafer-legend .die-bg{background:#edf0f5;border:1px solid #dfe6f0;}.zone-stats{display:flex;border:1px solid #e4eaf3;border-radius:6px;overflow:hidden;}.zone-stats button{flex:1;border:0;border-right:1px solid #e4eaf3;background:#fff;padding:13px 7px;text-align:center;}.zone-stats button:last-child{border:0;}.zone-stats button.active{background:#eef4ff;}.zone-stats button>span{display:block;font-size:12px;color:#8292ab;}.zone-stats strong{display:block;font-size:19px;font-weight:500;color:#4f6a93;margin:7px 0 5px;}.zone-stats strong small{font-size:12px;display:inline;color:#8498ba;margin-left:2px;}.zone-stats button>small{display:block;font-size:10px;color:#7f8ca1;}
</style>
